// src/utils/useScreenshot.js
import { useCallback, useState } from 'react';
import html2canvas from 'html2canvas';

/**
 * useScreenshot
 * - selector: 캡쳐할 DOM 노드(css selector) 기본값은 document.body 전체
 * - options: html2canvas 옵션 (ex. scale, logging 등)
 */
export function useScreenshot(selector = 'body', options = {}) {
  const [isCapturing, setIsCapturing] = useState(false);

  const captureAndShare = useCallback(async () => {
    setIsCapturing(true);
    try {
      // 1. 대상 DOM을 캡쳐
      const element = document.querySelector(selector);
      if (!element) throw new Error(`No element matches selector "${selector}"`);
      const canvas = await html2canvas(element, {
        // 성능·화질 조정 옵션
        scale: window.devicePixelRatio,
        useCORS: true,
        ...options,
      });

      // 2. Blob 변환
      const blob: Blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));

      // 3. Web Share API 사용 가능 여부 검사
      if (navigator.canShare && navigator.canShare({ files: [new File([blob], 'screenshot.png')] })) {
        await navigator.share({
          title: '화면 캡쳐',
          text: '화면을 공유합니다.',
          files: [new File([blob], 'screenshot.png', { type: 'image/png' })],
        });
      } else {
        // 폴백: 다운로드 링크 생성
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = 'screenshot.png';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        alert('공유 API를 지원하지 않는 환경입니다. 스크린샷을 다운로드했습니다.');
      }
    } catch (err) {
      console.error(err);
      alert('스크린샷 공유에 실패했습니다.');
    } finally {
      setIsCapturing(false);
    }
  }, [selector, options]);

  return { isCapturing, captureAndShare };
}
